# ==============================================================================
# figures.R
# Orestias skin microbiota
#
# Loads objects generated by pipeline.R and creates publication/review figures.
# Raw data, QIIME2 artifacts, intermediate tables, and results remain local.
# ==============================================================================

options(stringsAsFactors = FALSE)

suppressPackageStartupMessages({
  library(phyloseq)
  library(metacoder)
  library(tidyverse)
  library(ggplot2)
  library(vegan)
  library(agricolae)
  library(ggnewscale)
  library(igraph)
  library(ggraph)
  library(patchwork)
  library(scales)
})

if (file.exists("local_objects/pipeline_objects.RData")) {
  load("local_objects/pipeline_objects.RData")
} else {
  stop("Run pipeline.R first.")
}

dir.create("figures", showWarnings = FALSE, recursive = TRUE)

# ------------------------------------------------------------------------------
# 1. Taxonomic composition
# ------------------------------------------------------------------------------

bacteria.rel <- transform_sample_counts(bacteria, function(x) {
  if (sum(x) == 0) x else x / sum(x)
})

df <- psmelt(bacteria.rel)

top_phyla <- df %>%
  group_by(Phylum) %>%
  summarise(total = sum(Abundance), .groups = "drop") %>%
  arrange(desc(total)) %>%
  slice_head(n = 10) %>%
  pull(Phylum)

df$Phylum <- ifelse(df$Phylum %in% top_phyla, df$Phylum, "Other")

phylum_colors <- c(
  "Proteobacteria" = "#FF3333",
  "Bacteroidota" = "#9999FF",
  "Firmicutes" = "#33CCFF",
  "Actinobacteriota" = "#FFFF00",
  "Verrucomicrobiota" = "#0033CC",
  "Planctomycetota" = "#EEC84D",
  "Cyanobacteria" = "#FF00FF",
  "Patescibacteria" = "#33CC00",
  "Chloroflexi" = "#006633",
  "Other" = "grey80"
)

df$Phylum <- factor(
  df$Phylum,
  levels = names(sort(
    tapply(df$Abundance, df$Phylum, sum),
    decreasing = TRUE
  ))
)

p_phylum <- ggplot(
  df,
  aes(x = Sample, y = Abundance, fill = Phylum)
) +
  geom_col(width = 0.9, color = "white", linewidth = 0.1) +
  scale_y_continuous(labels = percent_format()) +
  scale_fill_manual(values = phylum_colors, drop = FALSE) +
  facet_grid(~Host, scales = "free_x", space = "free_x") +
  labs(x = NULL, y = "Relative abundance", fill = "Phylum") +
  theme_classic(base_size = 13) +
  theme(
    axis.text.x = element_text(angle = 45, hjust = 1),
    strip.background = element_blank(),
    strip.text = element_text(face = "italic")
  )

ggsave(
  "figures/01_phylum_relative_abundance.pdf",
  p_phylum, width = 11, height = 6
)

# Generic composition plots for the remaining ranks.
rank_plot <- function(rank, filename, width = 12, height = 8) {

  d <- psmelt(bacteria)

  gg <- ggplot(
    d,
    aes(x = Sample, y = Abundance, fill = .data[[rank]])
  ) +
    geom_col() +
    facet_grid(~Host, scales = "free_x", space = "free_x") +
    labs(x = NULL, y = "Abundance", fill = rank) +
    theme_classic(base_size = 12) +
    theme(axis.text.x = element_text(angle = 45, hjust = 1))

  ggsave(
    file.path("figures", filename),
    gg,
    width = width,
    height = height
  )
}

rank_plot("Class",  "02_class_composition.pdf")
rank_plot("Order",  "03_order_composition.pdf")
rank_plot("Family", "04_family_composition.pdf", width = 14, height = 9)
rank_plot("Genus",  "05_genus_composition.pdf", width = 16, height = 10)

