# ------------------------------------------------------------------------------
# 10. Mantel / Procrustes conceptual comparison
# ------------------------------------------------------------------------------

if (!is.null(mantel_tax_func)) {

  stats_df <- data.frame(
    comparison = c(
      "Taxonomy vs Function",
      "Taxonomy vs Network modules",
      "Network modules vs Function"
    ),
    Mantel_r = c(
      unname(mantel_tax_func$statistic),
      unname(mantel_tax_mod$statistic),
      unname(mantel_func_mod$statistic)
    ),
    Procrustes_r = c(
      proc_tax_func$t0,
      proc_tax_mod$t0,
      proc_func_mod$t0
    )
  )

  p <- ggplot(
    stats_df,
    aes(x = comparison, y = Mantel_r)
  ) +
    geom_col() +
    geom_text(
      aes(label = sprintf("Mantel r = %.2f", Mantel_r)),
      vjust = -0.4
    ) +
    ylim(0, max(stats_df$Mantel_r, na.rm = TRUE) * 1.25) +
    labs(x = NULL, y = "Mantel correlation") +
    theme_classic(base_size = 12) +
    theme(axis.text.x = element_text(angle = 25, hjust = 1))

  ggsave(
    "figures/25_taxonomy_network_function_Mantel.pdf",
    p, width = 8, height = 6
  )

  write.csv(
    stats_df,
    "figures/25_taxonomy_network_function_statistics.csv",
    row.names = FALSE
  )
}

# ------------------------------------------------------------------------------
# 11. Co-inertia
# ------------------------------------------------------------------------------

if (!is.null(coin_tax_func)) {

  pdf("figures/26_COI_taxonomy_function.pdf", width = 8, height = 7)
  plot(coin_tax_func)
  dev.off()

  pdf("figures/27_COI_taxonomy_modules.pdf", width = 8, height = 7)
  plot(coin_tax_mod)
  dev.off()

  pdf("figures/28_COI_modules_function.pdf", width = 8, height = 7)
  plot(coin_mod_func)
  dev.off()

  plot_coin <- function(coin, title = "") {

    df_X <- as.data.frame(coin$lX[, 1:2])
    df_Y <- as.data.frame(coin$lY[, 1:2])

    colnames(df_X) <- c("Axis1", "Axis2")
    colnames(df_Y) <- c("Axis1", "Axis2")

    df_X$sample <- rownames(df_X)
    df_Y$sample <- rownames(df_Y)

    df_arrow <- df_X %>%
      rename(x = Axis1, y = Axis2) %>%
      left_join(
        df_Y %>% rename(xend = Axis1, yend = Axis2),
        by = "sample"
      )

    df_arrow$dist <- sqrt(
      (df_arrow$x - df_arrow$xend)^2 +
        (df_arrow$y - df_arrow$yend)^2
    )

    ggplot() +
      geom_segment(
        data = df_arrow,
        aes(x = x, y = y, xend = xend, yend = yend, color = dist),
        arrow = arrow(length = unit(0.2, "cm")),
        linewidth = 1.1
      ) +
      geom_point(data = df_X, aes(Axis1, Axis2), size = 3) +
      geom_point(
        data = df_Y,
        aes(Axis1, Axis2),
        shape = 17,
        size = 3
      ) +
      geom_text(
        data = df_X,
        aes(Axis1, Axis2, label = sample),
        vjust = -1,
        size = 3
      ) +
      scale_color_gradient(low = "#a6cee3", high = "#e31a1c") +
      theme_minimal() +
      coord_equal() +
      labs(
        title = title,
        x = "Axis 1",
        y = "Axis 2",
        color = "Distance"
      )
  }

  p1 <- plot_coin(coin_tax_mod, "Taxonomy vs Modules")
  p2 <- plot_coin(coin_mod_func, "Modules vs Function")
  p3 <- plot_coin(coin_tax_func, "Taxonomy vs Function")

  pdf("figures/29_COI_all.pdf", width = 12, height = 9)
  print((p1 | p2) / (p3 | plot_spacer()))
  dev.off()
}

